#include <stdio.h>
#include <stdlib.h>

// opens the file again with a second stream and counts its characters
int size_now(const char *name) {
    FILE *f = fopen(name, "r");
    if (!f) {
        perror("fopen() failed");
        exit(EXIT_FAILURE);
    }
    int n = 0;
    while (fgetc(f) != EOF) {
        n++;
    }
    fclose(f);
    return n;
}

int main(void) {
    FILE *out = fopen("buf.txt", "w");
    if (!out) {
        perror("fopen() failed");
        exit(EXIT_FAILURE);
    }
    fputs("hello\n", out);
    printf("after fputs:  %d characters in buf.txt\n", size_now("buf.txt"));
    fflush(out);                    // deliver the buffer to the file now
    printf("after fflush: %d characters in buf.txt\n", size_now("buf.txt"));
    fputs("world\n", out);
    fclose(out);                    // fclose flushes too
    printf("after fclose: %d characters in buf.txt\n", size_now("buf.txt"));
    return 0;
}

