#include <stdio.h>
#include <stdlib.h>

int main(void) {
    FILE *f = fopen("tell.txt", "r");
    if (!f) {
        perror("fopen() failed");
        exit(EXIT_FAILURE);
    }
    int c;
    fseek(f, 7, SEEK_SET);           // 7 from the beginning
    c = fgetc(f);
    printf("SEEK_SET  7: %c, now at %ld\n", c, ftell(f));

    fseek(f, 4, SEEK_CUR);           // 4 more from where we are (8)
    c = fgetc(f);
    printf("SEEK_CUR  4: %c, now at %ld\n", c, ftell(f));

    fseek(f, -3, SEEK_CUR);          // a negative offset moves backwards
    c = fgetc(f);
    printf("SEEK_CUR -3: %c, now at %ld\n", c, ftell(f));

    fseek(f, -2, SEEK_END);          // 2 before the end (the end is 24)
    c = fgetc(f);
    printf("SEEK_END -2: %c, now at %ld\n", c, ftell(f));

    fseek(f, 0, SEEK_END);           // to the very end
    printf("file size = %ld\n", ftell(f));

    if (fseek(f, -100, SEEK_SET) != 0) {
        printf("fseek to -100 failed, still at %ld\n", ftell(f));
    }
    fclose(f);
    return 0;
}

