int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: replace_char file targetchar replacementchar\n");
        exit(EXIT_FAILURE);
    }
    FILE *f = fopen(argv[1], "r+");       // read AND write, keep the contents
    if (!f) {
        perror("fopen() failed");
        exit(EXIT_FAILURE);
    }
    char target = argv[2][0];             // first character of argument 2
    char replace = argv[3][0];            // first character of argument 3
    int c;
    while ((c = fgetc(f)) != EOF) {
        if (c == target) {
            fseek(f, -1, SEEK_CUR);       // back up onto the character just read
            fputc(replace, f);            // overwrite it
            fflush(f);                    // a write followed by a read needs this
        }
    }
    fclose(f);
    return 0;
}

