    fflush(out);
    c = fgetc(in);                         // ... but the indicator is still set
    printf("next fgetc: %d, feof = %d\n", c, feof(in) != 0);

    clearerr(in);                          // clear end-of-file (and error) indicators
    printf("after clearerr: feof = %d\n", feof(in) != 0);
    while ((c = fgetc(in)) != EOF) {
        putchar(c);
    }
