#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    int status = EXIT_FAILURE;            // assume failure until we finish
    if (argc != 3) {
        fprintf(stderr, "usage: catn infile outfile\n");
        exit(status);
    }

    // input file
    FILE *f_in = fopen(argv[1], "r");
    if (!f_in) {
        perror("fopen() failed");
        exit(status);
    }

    // output file
    FILE *f_out = fopen(argv[2], "w");
    if (!f_out) {
        perror("fopen() failed");
        fclose(f_in);
        exit(status);
    }

    // current line number (starting at 1)
    int line_num = 1;

    // input line buffer
    char str_in[100];
    while (fgets(str_in, 100, f_in) != NULL) {
        fprintf(f_out, "%03d %s", line_num, str_in);
        if (ferror(f_out)) {
            break;
        }
        line_num++;
    }
    if (ferror(f_in) || ferror(f_out)) {
        fprintf(stderr, "I/O error\n");
    }
    else if (feof(f_in)) {
        status = EXIT_SUCCESS;
    }

    fclose(f_in);
    fclose(f_out);
    return status;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    char name[20];
    int wins;
    int losses;
} team;

// Reads lines "name wins losses" from the file into t. Stores at most 30
// teams but returns the TOTAL number of lines. Exits with a message if the
// file cannot be opened or a line is not in the right form.
int read_teams(const char *filename, team t[static 30]) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        perror(filename);
        exit(EXIT_FAILURE);
    }
    char line[100];
    int n = 0;
    while (fgets(line, 100, f) != NULL) {
        team tmp;
        if (sscanf(line, "%19s %d %d", tmp.name, &tmp.wins, &tmp.losses) != 3) {
            fprintf(stderr, "%s: line %d is not \"name wins losses\"\n", filename, n + 1);
            fclose(f);
            exit(EXIT_FAILURE);
        }
        if (n < 30) {
            t[n] = tmp;                   // structs can be copied with =
        }
        n++;
    }
    fclose(f);
    return n;
}

// Swaps the team with the most wins into t[0] (the first one if several tie).
void best_to_front(int n, team t[static n]) {
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (t[i].wins > t[best].wins) {
            best = i;
        }
    }
    team tmp = t[0];
    t[0] = t[best];
    t[best] = tmp;
}

// Sorts by wins, most first: put the best of t[i..n-1] at t[i], for each i.
void sort_by_wins(int n, team t[static n]) {
    for (int i = 0; i < n - 1; i++) {
        best_to_front(n - i, t + i);      // t + i is the array starting at t[i]
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "usage: standings file\n");
        exit(EXIT_FAILURE);
    }
    team t[30];
    int total = read_teams(argv[1], t);
    int n = total < 30 ? total : 30;      // how many were actually stored
    sort_by_wins(n, t);
    for (int i = 0; i < n; i++) {
        printf("%-6s %2d-%d\n", t[i].name, t[i].wins, t[i].losses);
    }
    return 0;
}

