#include <stdio.h>
#include <stdlib.h>

// Flips the case of every letter in the file, in place.
// Returns the number of characters changed, or -1 if the file cannot be opened.
int swap_case_file(const char *filename) {
    FILE *f = fopen(filename, "r+");      // read and write, keep the contents
    if (!f) {
        return -1;
    }
    int changed = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        int d = c;
        if (c >= 'a' && c <= 'z') {
            d = c - 'a' + 'A';
        }
        else if (c >= 'A' && c <= 'Z') {
            d = c - 'A' + 'a';
        }
        if (d != c) {
            fseek(f, -1, SEEK_CUR);       // rule 1: reposition between read and write
            fputc(d, f);                  // overwrite the letter just read
            fflush(f);                    // rule 2: flush between write and read
            changed++;
        }
    }
    fclose(f);
    return changed;
}

