#include <stdio.h>
#include <stdlib.h>

// Prints the last n characters of the file (the whole file if it is shorter).
// Returns the number of characters printed, or -1 if the file cannot be opened.
long print_tail(const char *filename, long n) {
    FILE *f = fopen(filename, "r");
    if (f == NULL) {
        return -1;
    }
    fseek(f, 0, SEEK_END);                // go to the end ...
    long size = ftell(f);                 // ... so the position is the size
    long start = size - n;
    if (start < 0) {
        start = 0;
    }
    fseek(f, start, SEEK_SET);
    int c;
    while ((c = fgetc(f)) != EOF) {
        putchar(c);
    }
    fclose(f);
    return size - start;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char first[30];   // the first word of the line
    size_t length;    // the length of the line, not counting '\n'
} lineinfo;

void read_three(const char *filename, lineinfo info[static 3]) {
    FILE *f = fopen(filename, "r");
    if (f == NULL) {
        perror(filename);
        exit(EXIT_FAILURE);
    }
    char line[100];
    for (int i = 0; i < 3; i++) {
        if (fgets(line, 100, f) == NULL) {
            fprintf(stderr, "%s: fewer than 3 lines\n", filename);
            exit(EXIT_FAILURE);
        }
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[len - 1] = '\0';
            len--;
        }
        if (sscanf(line, "%29s", info[i].first) != 1) {
            fprintf(stderr, "%s: line %d has no words\n", filename, i + 1);
            exit(EXIT_FAILURE);
        }
        info[i].length = len;
    }
    fclose(f);
}
